import sys
from collections import deque

MAXN = 300
INF = int(1e9)

class Edge:
    def __init__(self, to, rev, flow, capacity):
        self.to = to
        self.rev = rev
        self.flow = flow
        self.capacity = capacity

adjacency = [[] for _ in range(MAXN)]

def addEdge(u, v, c, rc=0):
    forward = Edge(v, len(adjacency[v]), 0, c)
    backward = Edge(u, len(adjacency[u]), 0, rc)
    adjacency[u].append(forward)
    adjacency[v].append(backward)

distance = [0] * MAXN
ptr = [0] * MAXN
source = 0
sink = 0

def bfs():
    for i in range(len(distance)):
        distance[i] = -1
    distance[source] = 0
    q = deque([source])
    while q and distance[sink] == -1:
        u = q.popleft()
        for e in adjacency[u]:
            v = e.to
            if distance[v] == -1 and e.flow < e.capacity:
                distance[v] = distance[u] + 1
                q.append(v)
    return distance[sink] != -1

def dfs(u, flow):
    if u == sink or flow == 0:
        return flow
    while ptr[u] < len(adjacency[u]):
        e = adjacency[u][ptr[u]]
        v = e.to
        if distance[v] == distance[u] + 1:
            pushed = dfs(v, min(flow, e.capacity - e.flow))
            if pushed:
                e.flow += pushed
                adjacency[v][e.rev].flow -= pushed
                return pushed
        ptr[u] += 1
    return 0

def maxFlow():
    total = 0
    while bfs():
        for i in range(len(ptr)):
            ptr[i] = 0
        while True:
            pushed = dfs(source, INF)
            if not pushed:
                break
            total += pushed
    return total

deltaX = [-1, 0, 0, 1]
deltaY = [0, -1, 1, 0]

n, m = map(int, sys.stdin.readline().split())
labels = []
responses = []

for _ in range(n):
    labels.append(sys.stdin.readline().strip())
for _ in range(n):
    responses.append(sys.stdin.readline().strip())

obstacle = [[0]*n for _ in range(n)]
timeGrid = [[-1]*n for _ in range(n)]
distGrid = [[-1]*n for _ in range(n)]

for i in range(n):
    for j in range(n):
        obstacle[i][j] = 1 if labels[i][j] == 'Y' else 0

def bfsGrid(r, c, dis, check=False):
    for i in range(n):
        for j in range(n):
            dis[i][j] = -1
    dis[r][c] = 0
    q = deque()
    q.append((r, c))
    while q:
        p = q.popleft()
        if check and dis[p[0]][p[1]] == timeGrid[p[0]][p[1]]:
            continue
        for i in range(4):
            neighbor = (p[0] + deltaX[i], p[1] + deltaY[i])
            if (neighbor[0] < 0 or neighbor[0] >= n or neighbor[1] < 0 or neighbor[1] >= n or
                dis[neighbor[0]][neighbor[1]] != -1 or obstacle[neighbor[0]][neighbor[1]]):
                continue
            if (check and timeGrid[neighbor[0]][neighbor[1]] > -1 and
                dis[p[0]][p[1]] + 1 > timeGrid[neighbor[0]][neighbor[1]]):
                continue
            dis[neighbor[0]][neighbor[1]] = dis[p[0]][p[1]]]+1
            q.append(neighbor)

source = 2 * n * n + 5
sink = source + 1

for x in range(n):
    for y in range(n):
        if labels[x][y] == 'Z' or labels[x][y] == 'Y':
            continue
        addEdge(source, n * x + y, int(labels[x][y]))
        addEdge(n * n + n * x + y, sink, int(responses[x][y]))
        bfsGrid(x, y, distGrid, True)
        for xp in range(n):
            for yp in range(n):
                if distGrid[xp][yp] != -1 and distGrid[xp][yp] <= m:
                    addEdge(n * x + y, n * n + n * xp + yp, INF)

print(maxFlow())

